#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    cin.ignore();

    string line;
    getline(cin, line);

    string lineWithoutParentheses;
    int numberOfWordsInParentheses = 0;
    int i = 0;
    while (i < (int)line.size()) {
        if (line[i] == '(') {
            lineWithoutParentheses += "_";
            i++;
            string parenthesesWords;
            while (line[i] != ')') {
                parenthesesWords += line[i];
                i++;
            }
            stringstream ss(parenthesesWords);
            string word;
            while (getline(ss, word, '_')) {
                if (!word.empty()) {
                    numberOfWordsInParentheses++;
                }
            }
        } else {
            lineWithoutParentheses += line[i];
        }
        i++;
    }

    int maxWordWithoutParenthesesLength = 0;
    stringstream ss(lineWithoutParentheses);
    string word;
    while (ss >> word) {
        if ((int)word.length() > maxWordWithoutParenthesesLength) {
            maxWordWithoutParenthesesLength = word.length();
        }
    }

    cout << maxWordWithoutParenthesesLength << " " << numberOfWordsInParentheses << "\n";

    return 0;
}
